           return None;
       }
       let open_at = skip_whitespace(code, at + 1);
       let open = *code.get(open_at)?;
       let close = match open {
           '(' => ')',
           '[' => ']',
           '{' => '}',
           _ => return None,
       };
       let mut depth = 0usize;
       let mut names = Vec::new();
       let mut word = String::new();
       for &c in &code[open_at..] {
           if is_ident_char(c) {
               word.push(c);
               continue;
           }
           if !word.is_empty() {
               names.push(std::mem::take(&mut word));
           }
           if c == open {
               depth += 1;
           } else if c == close {
               depth -= 1;
               if depth == 0 {
                   return Some(names);
               }
           }
       }
